/**
 * LOCAL PROTOTYPE ONLY — future issuer boundary primitives.
 *
 * Grant identity is generated by the server, not selected by an OAuth client.
 * A credential embeds a non-secret 256-bit routing ID AND an independent
 * 256-bit random secret. DO authorization checks the full credential digest,
 * the registered client ID, scope and audience; routing never authenticates.
 *
 * This module does NOT provide a public OAuth endpoint or identity provider.
 */
export type CredentialKind = "access" | "refresh" | "code" | "browser" | "state";
const KIND_TAG: Record<CredentialKind, string> = {
  access: "nr1a", refresh: "nr1r", code: "nr1c", browser: "nr1b", state: "nr1s",
};
const HEX_256 = /^[0-9a-f]{64}$/;
const CLIENT_ID = /^[a-zA-Z0-9_-]{1,100}$/;
const randomHex = (): string => Array.from(crypto.getRandomValues(new Uint8Array(32)),
  n => n.toString(16).padStart(2, "0")).join("");

export function mintGrantId(): string {
  return randomHex();
}

export function mintBoundCredential(grantId: string, kind: CredentialKind): string {
  if (!HEX_256.test(grantId)) throw new Error("invalid_grant_id");
  return KIND_TAG[kind] + "." + grantId + "." + randomHex();
}

export async function sha256Hex(raw: string): Promise<string> {
  return Array.from(new Uint8Array(await crypto.subtle.digest(
    "SHA-256", new TextEncoder().encode(raw),
  )), n => n.toString(16).padStart(2, "0")).join("");
}

/**
 * Extract untrusted routing metadata from a credential. It grants nothing.
 * Caller MUST validate the returned digest + registered client against the
 * authoritative single-grant DO before authorizing any operation.
 */
export async function routeBoundCredential(
  raw: string, kind: CredentialKind,
): Promise<{ grantId: string; credentialHash: string } | null> {
  if (typeof raw !== "string" || raw.length > 220) return null;
  const parts = raw.split(".");
  const admitted = ["access", "browser", "state"].includes(kind) && parts.length === 5;
  if (parts.length !== (admitted ? 5 : 3) || parts[0] !== KIND_TAG[kind] ||
      !HEX_256.test(parts[1]) || !HEX_256.test(parts[2]) ||
      (admitted && (!/^[0-9]{1,12}$/.test(parts[3]) || !HEX_256.test(parts[4])))) return null;
  return { grantId: parts[1], credentialHash: await sha256Hex(raw) };
}

/** Compare normalized digests through native crypto, never a JS equality loop. */
async function equalDigest(a: Uint8Array<ArrayBuffer>, b: Uint8Array<ArrayBuffer>): Promise<boolean> {
  if (a.length !== 32 || b.length !== 32) return false;
  if ("timingSafeEqual" in crypto.subtle && typeof crypto.subtle.timingSafeEqual === "function")
    return crypto.subtle.timingSafeEqual(a, b);
  // Standard Web Crypto fallback for offline Node unit tests. Native HMAC
  // verification performs the comparison; the expected digest is not exposed.
  const key = await crypto.subtle.importKey("raw", b, { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
  const signature = await crypto.subtle.sign("HMAC", key, b);
  return crypto.subtle.verify("HMAC", key, signature, a);
}

/**
 * Local confidential-client verifier. A registered client and a SHA-256 hash
 * of its high-entropy secret MUST be provided by a trusted server config.
 * Never treat client_id, expectedSecretHash, or authorization scope as user
 * input. Production needs proper registration, rotation and rate limits.
 */
export async function verifyConfidentialClient(
  header: string | null,
  registeredClientId: string,
  registeredSecretHash: string,
): Promise<boolean> {
  if (!header || !CLIENT_ID.test(registeredClientId) ||
      !HEX_256.test(registeredSecretHash) || header.length > 512 ||
      !header.startsWith("Basic ")) return false;
  let parsed: string;
  try { parsed = atob(header.slice(6)); } catch { return false; }
  const split = parsed.indexOf(":");
  if (split < 1 || split > 100) return false;
  const clientId = parsed.slice(0, split);
  const secret = parsed.slice(split + 1);
  if (!CLIENT_ID.test(clientId) || secret.length < 32 || secret.length > 256) return false;
  const candidate = new Uint8Array(await crypto.subtle.digest(
    "SHA-256", new TextEncoder().encode(secret),
  ));
  const expected = Uint8Array.from(registeredSecretHash.match(/.{2}/g)!,
    pair => Number.parseInt(pair, 16));
  // Both checks run after digesting a syntactically valid candidate.
  return await equalDigest(candidate, expected) && clientId === registeredClientId;
}
